import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const SuccessCheck = () => {
  const navigate = useNavigate();
  const location = useLocation();
  
  // Берем email из стейта, если передали, или показываем заглушку
  const email = location.state?.email || '';
  
  // Получаем имя для приветствия (если передали в стейте, иначе "Студент")
  const firstName = location.state?.firstName || 'Александра';

  return (
    <div className="min-h-screen w-full bg-primary flex flex-col px-6">
      <div className="mx-auto flex w-full max-w-[400px] flex-1 flex-col">
        
        {/* Кнопка назад */}
        <button
          type="button"
          aria-label="Назад"
          onClick={() => navigate('/')}
          className="mt-10 flex h-10 w-10 items-center justify-center rounded-full bg-black text-white"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>

        {/* Блик */}
        <div className="flex justify-center mt-6 mb-8">
          <div
            className="h-[150px] w-[240px] rounded-full blur-[20px] opacity-90"
            style={{
              background: 'radial-gradient(ellipse closest-side at center, #FF6600 0%, #FFCC00 36%, #FF0055 75%, rgba(255, 0, 85, 0) 100%)',
            }}
          />
        </div>

        {/* Заголовок */}
        <h1 className="text-[34px] leading-[110%] font-semibold text-black tracking-tight">
          Привет, {firstName}
        </h1>

        <p className="mt-2 text-[14px] leading-[120%] text-gray">
          Вы успешно создали аккаунт
        </p>

        {/* Огромная галочка (как на скриншоте) */}
        <div className="flex flex-1 items-center justify-center mb-12">
          <svg width="120" height="120" viewBox="0 0 24 24" fill="none" stroke="#0D0C0C" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M20 6L9 17l-5-5" />
          </svg>
        </div>

      </div>
    </div>
  );
};

export default SuccessCheck;
